import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
const root = new URL('../', import.meta.url);
const out = new URL('packages/generated/server-markdown.mjs', root);
const result = await Bun.build({
  entrypoints: [fileURLToPath(new URL('packages/parsers/markdown.mjs', root))],
  target: 'bun',
  format: 'esm',
  minify: true,
  write: false,
});
if (!result.success || result.outputs.length !== 1)
  throw new Error('Server Markdown parser bundling failed: ' + result.logs.map(String).join('\n'));
const content =
  '// Generated by scripts/server-markdown.mjs from pinned dependencies. Do not edit.\n' +
  (await result.outputs[0].text());
await mkdir(new URL('packages/generated/', root), { recursive: true });
let previous;
try {
  previous = await readFile(out, 'utf8');
} catch (error) {
  if (error.code !== 'ENOENT') throw error;
}
if (previous !== content) await writeFile(out, content);
console.log(
  'Generated self-contained server Markdown parser (' + Buffer.byteLength(content) + ' bytes).',
);
